// Author: MiYu. Update fog only when simulation visibility changes; project camera-space positions back into map UVs.
#include "fog_render.h"

namespace war3 {
void FogRender::begin(const FogGrid& grid,const D3DMATRIX& view) {
    auto device=renderer_.device();if(!texture_ || width_!=grid.width || height_!=grid.height){texture_.Reset();width_=grid.width;height_=grid.height;D3DCAPS9 caps{};device->GetDeviceCaps(&caps);discard_=renderer_.resourcePool()==D3DPOOL_DEFAULT;dynamic_=!discard_ || (caps.Caps2&D3DCAPS2_DYNAMICTEXTURES)!=0;if(dynamic_){auto result=device->CreateTexture(width_,height_,1,discard_?D3DUSAGE_DYNAMIC:0,D3DFMT_A8R8G8B8,renderer_.resourcePool(),&texture_,nullptr);if(FAILED(result))dynamic_=false;}stamp_=0;}
    if(stamp_!=grid.stamp){if(dynamic_){D3DLOCKED_RECT lock{};auto result=texture_->LockRect(0,&lock,nullptr,discard_?D3DLOCK_DISCARD:0);if(FAILED(result))throw std::runtime_error("Cannot update fog texture");for(unsigned y=0;y<height_;++y)std::memcpy(static_cast<char*>(lock.pBits)+y*lock.Pitch,grid.pixels.data()+size_t(y)*width_,size_t(width_)*4);result=texture_->UnlockRect(0);if(FAILED(result))throw std::runtime_error("Cannot unlock fog texture");}else texture_=renderer_.texture(width_,height_,grid.pixels);stamp_=grid.stamp;}
    auto transform=DirectX::XMMatrixInverse(nullptr,sceneMatrix(view))*DirectX::XMMatrixScaling(1/(grid.width*64.f),1/(grid.height*64.f),1)*DirectX::XMMatrixTranslation(-grid.origin[0]/(grid.width*64.f),-grid.origin[1]/(grid.height*64.f),0);auto matrix=sceneMatrix(transform);device->SetTransform(D3DTS_TEXTURE1,&matrix);device->SetTexture(1,texture_.Get());device->SetTextureStageState(1,D3DTSS_TEXCOORDINDEX,D3DTSS_TCI_CAMERASPACEPOSITION|1);device->SetTextureStageState(1,D3DTSS_TEXTURETRANSFORMFLAGS,D3DTTFF_COUNT2);device->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_MODULATE);device->SetTextureStageState(1,D3DTSS_COLORARG1,D3DTA_CURRENT);device->SetTextureStageState(1,D3DTSS_COLORARG2,D3DTA_TEXTURE);device->SetTextureStageState(1,D3DTSS_ALPHAOP,D3DTOP_SELECTARG1);device->SetTextureStageState(1,D3DTSS_ALPHAARG1,D3DTA_CURRENT);device->SetSamplerState(1,D3DSAMP_MINFILTER,D3DTEXF_LINEAR);device->SetSamplerState(1,D3DSAMP_MAGFILTER,D3DTEXF_LINEAR);device->SetSamplerState(1,D3DSAMP_ADDRESSU,D3DTADDRESS_CLAMP);device->SetSamplerState(1,D3DSAMP_ADDRESSV,D3DTADDRESS_CLAMP);
}
void FogRender::end() {auto device=renderer_.device();device->SetTextureStageState(1,D3DTSS_COLOROP,D3DTOP_DISABLE);device->SetTextureStageState(1,D3DTSS_ALPHAOP,D3DTOP_DISABLE);device->SetTextureStageState(1,D3DTSS_TEXCOORDINDEX,1);device->SetTextureStageState(1,D3DTSS_TEXTURETRANSFORMFLAGS,D3DTTFF_DISABLE);device->SetTexture(1,nullptr);}
}
